func (m dashModel) handleCommitsKey(key string) (tea.Model, tea.Cmd) {
	commits := m.focusedCommits()
	switch key {
	case "up", "k":
		if m.commitCursor > 0 {
			m.commitCursor--
			return m, m.dispatchCommitDetail()
		}
	case "down", "j":
		if m.commitCursor < len(commits)-1 {
			m.commitCursor++
			return m, m.dispatchCommitDetail()
		}
	case "g", "home":
		m.commitCursor = 0
		return m, m.dispatchCommitDetail()
	case "G", "end":
		m.commitCursor = max(0, len(commits)-1)
		return m, m.dispatchCommitDetail()
	}
	return m, nil
}

